use std::collections::HashMap;impl Solution{pub fn palindrome_pairs(w:Vec<String>)->Vec<Vec<i32>>{fn pal(s:&[u8])->bool{s.iter().eq(s.iter().rev())}let mut m=HashMap::new();for(i,s)in w.iter().enumerate(){m.insert(s.clone(),i as i32);}let mut o=vec![];for(i,s)in w.iter().enumerate(){for k in 0..=s.len(){if pal(&s.as_bytes()[..k]){let x:String=s[k..].chars().rev().collect();if let Some(&j)=m.get(&x){if j!=i as i32{o.push(vec![j,i as i32]);}}}if k<s.len()&&pal(&s.as_bytes()[k..]){let x:String=s[..k].chars().rev().collect();if let Some(&j)=m.get(&x){if j!=i as i32{o.push(vec![i as i32,j]);}}}}}o}}
